export interface ApiUser { id: number | string; firstname: string; lastname?: string; username?: string; city?: string; country?: string; profile_url?: string; scopes?: string; last_sync_at?: string; strava_connected?: boolean; }
export interface ApiSession { authenticated: boolean; user: ApiUser | null; csrf_token: string; }
export interface ApiDashboard { user?: ApiUser; stats?: { total?: number; distance?: number; moving_time?: number; elevation?: number }; trend?: unknown[]; activities?: unknown[]; }
export interface ApiActivities { activities: unknown[]; count: number; }
export interface ApiSegments { segments?: unknown[]; groups?: unknown[]; strava_segments?: unknown[]; }
export interface StravaAuthorization { authorization_url: string; }

@Injectable({ providedIn: 'root' })
export class CsrfStore { readonly token = signal(''); set(token: string) { this.token.set(token || ''); } clear() { this.token.set(''); } }

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient); readonly baseUrl = 'https://alon.one/sports/api/v1';
  session() { return this.http.get<ApiSession>(`${this.baseUrl}/auth/session`); }
  csrfToken() { return this.http.get<{ csrf_token: string }>(`${this.baseUrl}/auth/csrf`); }
  stravaAuthorization() { return this.http.get<StravaAuthorization>(`${this.baseUrl}/auth/strava`); }
  dashboard() { return this.http.get<ApiDashboard>(`${this.baseUrl}/dashboard`); }
  activities(limit = 100) { return this.http.get<ApiActivities>(`${this.baseUrl}/activities?limit=${limit}`); }
  activity(id: string) { return this.http.get<Record<string, unknown>>(`${this.baseUrl}/activities/${encodeURIComponent(id)}`); }
  segments() { return this.http.get<ApiSegments>(`${this.baseUrl}/segments`); }
  segment(id: string) { return this.http.get<Record<string, unknown>>(`${this.baseUrl}/segments/${encodeURIComponent(id)}`); }
  mutation<T>(method: 'post' | 'put' | 'delete', path: string, body?: unknown) { return this.http.request<T>(method, `${this.baseUrl}${path}`, { body }); }
}

@Injectable({ providedIn: 'root' })
export class AuthStore {
  readonly status = signal<'loading' | 'authenticated' | 'anonymous'>('loading'); readonly authenticated = computed(() => this.status() === 'authenticated'); readonly user = signal<ApiUser | null>(null); readonly error = signal('');
  private init$?: Observable<boolean>; private readonly api = inject(ApiService); private readonly csrf = inject(CsrfStore);
  initialize() { if (!this.init$) this.init$ = this.api.session().pipe(tap(session => this.applySession(session)), map(session => session.authenticated), catchError(() => { this.status.set('anonymous'); this.user.set(null); return of(false); }), shareReplay(1)); return this.init$; }
  private applySession(session: ApiSession) { this.csrf.set(session.csrf_token); this.user.set(session.user); this.status.set(session.authenticated ? 'authenticated' : 'anonymous'); }
  loginWithStrava() { this.error.set(''); this.api.stravaAuthorization().subscribe({ next: response => { if (typeof window !== 'undefined') window.location.assign(response.authorization_url); }, error: () => this.error.set('No se ha podido iniciar la conexión con Strava.') }); }
  logout() { this.api.mutation<{ ok: boolean }>('post', '/auth/logout').pipe(catchError(() => of({ ok: false }))).subscribe(() => { this.csrf.clear(); this.user.set(null); this.status.set('anonymous'); }); }
}

@Injectable({ providedIn: 'root' })
export class SportsDataStore {
  readonly activities = signal<Activity[]>([]); readonly segments = signal<Segment[]>([]); readonly dashboard = signal<ApiDashboard | null>(null); readonly loading = signal(false); readonly error = signal(''); private readonly api = inject(ApiService);
  loadDashboard() { if (this.dashboard()) return; this.loading.set(true); this.api.dashboard().subscribe({ next: value => this.dashboard.set(value), error: () => this.error.set('No se ha podido cargar el resumen.'), complete: () => this.loading.set(false) }); }
  loadActivities() { if (this.activities().length) return; this.loading.set(true); this.api.activities(100).subscribe({ next: response => this.activities.set(response.activities.map(item => this.toActivity(item))), error: () => this.error.set('No se han podido cargar las actividades.'), complete: () => this.loading.set(false) }); }
  loadSegments() { if (this.segments().length) return; this.api.segments().subscribe({ next: response => this.segments.set((response.segments ?? []).map(item => this.toSegment(item))), error: () => this.error.set('No se han podido cargar los segmentos.') }); }
  toActivity(raw: unknown): Activity { const item: any = raw ?? {}; const sport = this.sport(item.sport_type); const distance = Number(item.distance ?? 0) / 1000; const moving = Number(item.moving_time ?? 0); const speed = Number(item.average_speed ?? 0); return { id: String(item.id), name: String(item.name ?? 'Actividad sin nombre'), sport_type: sport, date: this.dateLabel(item.start_date_local ?? item.start_date), distance, moving_time: Math.round(moving / 60), elevation: Math.round(Number(item.total_elevation_gain ?? 0)), pace: sport === 'Ride' ? `${(speed * 3.6).toFixed(1)} km/h` : this.pace(speed, distance), effort: 0, color: sport === 'Ride' ? '#76a8ff' : sport === 'Walk' ? '#f0a45d' : '#c9f45b', location: String(item.location_city ?? item.city ?? item.location ?? 'Sin ubicación') }; }
  toSegment(raw: unknown): Segment { const item: any = raw ?? {}; const distance = Number(item.distance ?? 0); return { id: String(item.id), name: String(item.name ?? 'Segmento'), distance: typeof item.distance === 'string' ? item.distance : `${(distance / 1000).toFixed(2)} km`, elevation: `+${Math.round(Number(item.elevation_gain ?? item.total_elevation_gain ?? 0))} m`, best: this.duration(Number(item.best_time ?? item.pr_time ?? 0)), attempts: Number(item.attempts ?? item.effort_count ?? 0), rank: item.rank ? String(item.rank) : '—', color: '#c9f45b', trend: [34, 27, 30, 22, 24, 16, 19, 12] }; }
  private sport(value: unknown): Sport { return String(value).toLowerCase().includes('ride') || String(value).toLowerCase().includes('cycl') ? 'Ride' : String(value).toLowerCase().includes('walk') ? 'Walk' : 'Run'; }
  private pace(speed: number, distance: number) { const seconds = speed > 0 ? 1000 / speed : distance > 0 ? 3600 / distance : 0; return seconds ? `${Math.floor(seconds / 60)}:${String(Math.round(seconds % 60)).padStart(2, '0')} /km` : '—'; }
  private duration(seconds: number) { return seconds ? `${Math.floor(seconds / 60)}:${String(Math.round(seconds % 60)).padStart(2, '0')}` : '—'; }
  private dateLabel(value: unknown) { return value ? String(value).replace('T', ' · ').slice(0, 22) : 'Sin fecha'; }
}

