@Component({ selector: 'app-live-dashboard', imports: [RouterLink, MatIconModule, MiniChart, ActivityCard], template: `<section class="page dashboard-page"><div class="page-heading"><div><p class="eyebrow">TU RESUMEN REAL</p><h1>Hola, {{ firstName() }} <span>✦</span></h1><p class="muted">Datos sincronizados desde Alon Sports.</p></div><button class="round-button" routerLink="/app/import"><mat-icon>add</mat-icon></button></div><div class="week-banner"><div><p class="eyebrow lime">ESTA SEMANA</p><strong>{{ loading() ? 'Cargando tu actividad…' : 'Tu mejor versión se construye aquí.' }}</strong></div><div class="week-ring"><span>74<small>%</small></span></div></div><div class="stats-grid"><article class="stat-card"><span class="stat-label">DISTANCIA</span><strong>{{ distance() }} <small>km</small></strong><span class="stat-change positive"><mat-icon>trending_up</mat-icon> Datos API</span></article><article class="stat-card"><span class="stat-label">TIEMPO EN MOVIMIENTO</span><strong>{{ movingTime() }} <small>min</small></strong><span class="stat-change positive"><mat-icon>trending_up</mat-icon> Datos API</span></article><article class="stat-card"><span class="stat-label">DESNIVEL</span><strong>{{ elevation() }} <small>m</small></strong><span class="stat-change neutral">Acumulado</span></article></div><article class="chart-card"><div class="card-heading"><div><span class="eyebrow">VOLUMEN · DATOS DEL DASHBOARD</span><h2>Tu ritmo, en perspectiva</h2></div></div><div class="chart-total"><strong>{{ distance() }}</strong><span> km sincronizados</span><span class="positive">Sesión activa</span></div><app-mini-chart /><div class="chart-axis"><span>API</span><span>ACTIVIDADES</span><span>REAL</span></div></article><section class="section-heading"><div><p class="eyebrow">TU HISTORIAL</p><h2>Últimas actividades</h2></div><a routerLink="/app/activities">Ver todas <mat-icon>arrow_forward</mat-icon></a></section><div class="activity-list">@for (activity of activities(); track activity.id) { <app-activity-card [activity]="activity" /> }</div>@if (error()) { <p class="api-error">{{ error() }}</p> }</section>`, styleUrl: './app.css', changeDetection: ChangeDetectionStrategy.OnPush })
export class LiveDashboardPage { private readonly data = inject(SportsDataStore); private readonly auth = inject(AuthStore); readonly loading = this.data.loading; readonly error = this.data.error; readonly activities = computed(() => this.data.activities().slice(0, 3)); readonly firstName = computed(() => this.auth.user()?.firstname ?? 'Atleta'); readonly distance = computed(() => this.formatNumber(this.data.dashboard()?.stats?.distance ?? 0)); readonly movingTime = computed(() => Math.round(Number(this.data.dashboard()?.stats?.moving_time ?? 0) / 60)); readonly elevation = computed(() => Math.round(Number(this.data.dashboard()?.stats?.elevation ?? 0))); constructor() { this.data.loadDashboard(); this.data.loadActivities(); } private formatNumber(meters: number) { return (Number(meters) / 1000).toFixed(1); } }

