@Component({ selector: 'app-live-segments', imports: [RouterLink, MatIconModule, SegmentSpark], template: `<section class="page"><div class="page-heading"><div><p class="eyebrow">DATOS SINCRONIZADOS</p><h1>Segmentos</h1><p class="muted">Tus segmentos propios calculados por la API.</p></div><button class="round-button" routerLink="/app/segments/new"><mat-icon>add</mat-icon></button></div><div class="segment-summary"><div><strong>{{ segments().length }}</strong><span>segmentos cargados</span></div><div><strong>API</strong><span>fuente de datos</span></div><div><strong>Live</strong><span>último estado</span></div></div><div class="section-heading compact"><div><p class="eyebrow">TUS SEGMENTOS</p><h2>Último rendimiento</h2></div></div><div class="segment-list">@for (segment of segments(); track segment.id) { <a class="segment-card" [routerLink]="['/app/segments', segment.id]"><div class="segment-card-top"><span class="segment-color" [style.background]="segment.color"></span><div><h3>{{ segment.name }}</h3><p>{{ segment.distance }} · {{ segment.elevation }}</p></div><mat-icon>arrow_outward</mat-icon></div><div class="segment-card-bottom"><div><span class="eyebrow">MEJOR TIEMPO</span><strong>{{ segment.best }}</strong></div><div><span class="eyebrow">POSICIÓN</span><strong>{{ segment.rank }}</strong></div><app-segment-spark [data]="segment.trend" [color]="segment.color" /></div></a>}</div>@if (error()) { <p class="api-error">{{ error() }}</p> }</section>`, styleUrl: './app.css', changeDetection: ChangeDetectionStrategy.OnPush })
export class LiveSegmentsPage { private readonly data = inject(SportsDataStore); readonly segments = computed(() => this.data.segments()); readonly error = this.data.error; constructor() { this.data.loadSegments(); } }

@Component({ selector: 'app-live-activity', imports: [RouterLink, MatIconModule, RouteMap], template: `<section class="page activity-page"><div class="back-row"><a routerLink="/app/activities"><mat-icon>arrow_back</mat-icon> Actividades</a><a class="icon-button" [routerLink]="['/app/activity', id, 'share']"><mat-icon>share</mat-icon></a></div>@if (loading()) { <div class="loading-state"><mat-icon>sync</mat-icon><p>Cargando detalle de actividad…</p></div> } @else { <div class="activity-hero"><div class="sport-pill"><mat-icon>directions_run</mat-icon> {{ sportLabel() }}</div><p class="eyebrow">{{ activity().date }} · {{ activity().location }}</p><h1>{{ activity().name }}</h1><p class="muted">Detalle real de tu salida.</p></div><div class="activity-metrics"><div><span>Distancia</span><strong>{{ activity().distance.toFixed(2) }} <small>km</small></strong></div><div><span>Tiempo</span><strong>{{ activity().moving_time }} <small>min</small></strong></div><div><span>Ritmo / velocidad</span><strong>{{ activity().pace }}</strong></div><div><span>Desnivel</span><strong>{{ activity().elevation }} <small>m</small></strong></div></div><nav class="sub-tabs"><a [routerLink]="['/app/activity', id, 'overview']" [class.active]="section === 'overview'">Resumen</a><a [routerLink]="['/app/activity', id, 'charts']" [class.active]="section === 'charts'">Gráficos</a><a [routerLink]="['/app/activity', id, 'stats']" [class.active]="section === 'stats'">Estadísticas</a><a [routerLink]="['/app/activity', id, 'segments']" [class.active]="section === 'segments'">Segmentos</a><a [routerLink]="['/app/activity', id, 'details']" [class.active]="section === 'details'">Datos</a></nav>@if (section === 'overview' || section === 'charts') { <app-route-map [routePoints]="routePoints()" /><div class="insight-card"><span class="insight-icon"><mat-icon>cloud_done</mat-icon></span><div><strong>Detalle cargado desde la API</strong><p>{{ streamsLabel() }}</p></div></div> } @else if (section === 'segments') { <div class="segment-list">@for (segment of segments(); track segment.id) { <a class="segment-row large" [routerLink]="['/app/segments', segment.id]"><span class="segment-color" [style.background]="segment.color"></span><div><strong>{{ segment.name }}</strong><p>{{ segment.distance }} · {{ segment.elevation }}</p><small>Tu posición: <b>{{ segment.rank }}</b></small></div><b>{{ segment.best }}</b><mat-icon>chevron_right</mat-icon></a>}</div> } @else { <div class="detail-grid"><article class="detail-card"><span>RITMO MEDIO</span><strong>{{ activity().pace }}</strong><p>Dato de actividad</p></article><article class="detail-card"><span>DESNIVEL</span><strong>{{ activity().elevation }} <small>m</small></strong><p>Ganancia total</p></article></div><div class="details-list"><div><span>Nombre</span><strong>{{ activity().name }}</strong></div><div><span>Fecha</span><strong>{{ activity().date }}</strong></div><div><span>Fuente</span><strong>Alon Sports API <span class="source-dot"></span></strong></div></div> } } @if (error()) { <p class="api-error">{{ error() }}</p> }</section>`, styleUrl: './app.css', changeDetection: ChangeDetectionStrategy.OnPush })
export class LiveActivityPage { private readonly route = inject(ActivatedRoute); private readonly api = inject(ApiService); private readonly data = inject(SportsDataStore); readonly id = this.route.snapshot.paramMap.get('id') ?? ''; readonly section = this.route.snapshot.paramMap.get('section') ?? 'overview'; readonly loading = signal(true); readonly error = signal(''); readonly detail = signal<Record<string, any> | null>(null); readonly activity = computed(() => this.detail() ? this.data.toActivity(this.detail()?.['activity'] ?? this.detail()) : ACTIVITIES.find(item => item.id === this.id) ?? ACTIVITIES[0]); readonly segments = computed(() => { const raw = this.detail()?.['segments']; return Array.isArray(raw) && raw.length ? raw.map(item => this.data.toSegment(item)) : SEGMENTS; }); readonly routePoints = computed<L.LatLngExpression[]>(() => { const raw = this.detail()?.['streams']?.['latlng']; return Array.isArray(raw) && raw.length > 1 ? raw as L.LatLngExpression[] : DEFAULT_ROUTE; }); readonly streamsLabel = computed(() => this.detail()?.['streams'] ? 'Streams GPS, distancia y métricas disponibles.' : 'La actividad no incluye streams GPS disponibles.'); readonly sportLabel = computed(() => this.activity().sport_type === 'Ride' ? 'Ciclismo' : this.activity().sport_type === 'Walk' ? 'Caminar' : 'Correr'); constructor() { this.api.activity(this.id).subscribe({ next: value => this.detail.set(value), error: () => this.error.set('No se ha podido cargar el detalle real.'), complete: () => this.loading.set(false) }); } }
